  backoffLimit: 6
  activeDeadlineSeconds: 300
  annotations: {}
  labels: {}

priorityClassName: ""

---
# FILE: templates/_helpers.tpl
{{- define "postgres.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" -}}
{{- end -}}

{{- define "postgres.fullname" -}}
{{- if .Values.fullnameOverride -}}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- $name := include "postgres.name" . -}}
{{- if contains $name .Release.Name -}}
{{- .Release.Name | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" -}}
{{- end -}}
{{- end -}}
{{- end -}}

{{- define "postgres.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" -}}
{{- end -}}

{{- define "postgres.labels" -}}
helm.sh/chart: {{ include "postgres.chart" . }}
app.kubernetes.io/name: {{ include "postgres.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- with .Values.podLabels }}
{{ toYaml . | indent 0 }}
{{- end }}
{{- end -}}

{{- define "postgres.selectorLabels" -}}
app.kubernetes.io/name: {{ include "postgres.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end -}}

{{- define "postgres.serviceHeadlessName" -}}
{{ include "postgres.fullname" . }}-headless
{{- end -}}

{{- define "postgres.secretName" -}}
{{ include "postgres.fullname" . }}-credentials
{{- end -}}
---
# FILE: templates/secret.yaml
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "postgres.secretName" . }}
  labels:
    {{- include "postgres.labels" . | nindent 4 }}
type: Opaque
data:
  {{- $existing := (lookup "v1" "Secret" .Release.Namespace (include "postgres.secretName" .)) }}
  {{- $creds := dict -}}
  {{- /* postgres username */ -}}
  {{- $_ := set $creds "pgUser" (.Values.postgresql.username | default "postgres") -}}
  {{- /* postgres password: prefer value, else existing secret, else generate */ -}}
  {{- if .Values.postgresql.password }}
    {{- $_ := set $creds "pgPass" .Values.postgresql.password -}}
  {{- else if $existing }}
    {{- $_ := set $creds "pgPass" (b64dec (index $existing.data "postgresPassword")) -}}
  {{- else }}
    {{- $_ := set $creds "pgPass" (randAlphaNum 24) -}}
  {{- end -}}
  {{- /* app database name */ -}}
  {{- $_ := set $creds "appDb" (.Values.postgresql.database | default "appdb") -}}
  {{- /* app username */ -}}
  {{- $_ := set $creds "appUser" (.Values.postgresql.appUser | default "appuser") -}}
  {{- /* app password: prefer value, else existing secret, else generate */ -}}
  {{- if .Values.postgresql.appPassword }}
    {{- $_ := set $creds "appPass" .Values.postgresql.appPassword -}}
  {{- else if $existing }}
    {{- $_ := set $creds "appPass" (b64dec (index $existing.data "appPassword")) -}}
  {{- else }}
    {{- $_ := set $creds "appPass" (randAlphaNum 24) -}}
  {{- end }}

  postgresUsername: {{ get $creds "pgUser" | b64enc | quote }}
  postgresPassword: {{ get $creds "pgPass" | b64enc | quote }}
  appDatabase: {{ get $creds "appDb" | b64enc | quote }}
  appUsername: {{ get $creds "appUser" | b64enc | quote }}
  appPassword: {{ get $creds "appPass" | b64enc | quote }}
---
# FILE: templates/service-headless.yaml
apiVersion: v1
kind: Service
metadata:
  name: {{ include "postgres.serviceHeadlessName" . }}
  labels:
    {{- include "postgres.labels" . | nindent 4 }}
  {{- with .Values.service.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  clusterIP: None
  publishNotReadyAddresses: true
  ports:
    - name: postgres
      port: {{ .Values.service.port }}
      targetPort: postgres
      protocol: TCP
  selector:
    {{- include "postgres.selectorLabels" . | nindent 4 }}
---
# FILE: templates/statefulset.yaml
apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: {{ include "postgres.fullname" . }}
  labels:
    {{- include "postgres.labels" . | nindent 4 }}
spec:
  serviceName: {{ include "postgres.serviceHeadlessName" . }}
  replicas: {{ .Values.replicaCount }}
  podManagementPolicy: OrderedReady
  selector:
    matchLabels:
      {{- include "postgres.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "postgres.selectorLabels" . | nindent 8 }}
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- if .Values.priorityClassName }}
      priorityClassName: {{ .Values.priorityClassName | quote }}
      {{- end }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      terminationGracePeriodSeconds: {{ .Values.terminationGracePeriodSeconds }}
      containers:
        - name: postgres
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          securityContext:
            {{- toYaml .Values.containerSecurityContext | nindent 12 }}
          ports:
            - name: postgres
              containerPort: {{ .Values.service.port }}
              protocol: TCP
          env:
            - name: POSTGRES_USER
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: postgresUsername
            - name: POSTGRES_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: postgresPassword
          volumeMounts:
            - name: data
              mountPath: /var/lib/postgresql/data
          {{- if .Values.probes.startup.enabled }}
          startupProbe:
            exec:
              command:
                - sh
                - -c
                - exec pg_isready -U "$POSTGRES_USER" -d postgres -h 127.0.0.1 -p {{ .Values.service.port }}
            failureThreshold: {{ .Values.probes.startup.failureThreshold }}
            periodSeconds: {{ .Values.probes.startup.periodSeconds }}
          {{- end }}
          {{- if .Values.probes.liveness.enabled }}
          livenessProbe:
            exec:
              command:
                - sh
                - -c
                - exec pg_isready -U "$POSTGRES_USER" -d postgres -h 127.0.0.1 -p {{ .Values.service.port }}
            initialDelaySeconds: {{ .Values.probes.liveness.initialDelaySeconds }}
            periodSeconds: {{ .Values.probes.liveness.periodSeconds }}
            timeoutSeconds: {{ .Values.probes.liveness.timeoutSeconds }}
            failureThreshold: {{ .Values.probes.liveness.failureThreshold }}
          {{- end }}
          {{- if .Values.probes.readiness.enabled }}
          readinessProbe:
            exec:
              command:
                - sh
                - -c
                - exec pg_isready -U "$POSTGRES_USER" -d postgres -h 127.0.0.1 -p {{ .Values.service.port }}
            initialDelaySeconds: {{ .Values.probes.readiness.initialDelaySeconds }}
            periodSeconds: {{ .Values.probes.readiness.periodSeconds }}
            timeoutSeconds: {{ .Values.probes.readiness.timeoutSeconds }}
            failureThreshold: {{ .Values.probes.readiness.failureThreshold }}
          {{- end }}
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
  volumeClaimTemplates:
    {{- if .Values.persistence.enabled }}
    - metadata:
        name: data
        labels:
          {{- include "postgres.labels" . | nindent 10 }}
      spec:
        accessModes: {{ toYaml .Values.persistence.accessModes | nindent 10 }}
        {{- if .Values.persistence.storageClass }}
        storageClassName: {{ .Values.persistence.storageClass | quote }}
        {{- end }}
        resources:
          requests:
            storage: {{ .Values.persistence.size | quote }}
    {{- else }}
    # No PVCs when persistence is disabled; use emptyDir via ephemeral volume in pod spec
    {{- end }}
---
# FILE: templates/job-initdb.yaml
apiVersion: batch/v1
kind: Job
metadata:
  name: {{ include "postgres.fullname" . }}-initdb
  labels:
    {{- include "postgres.labels" . | nindent 4 }}
  annotations:
    "helm.sh/hook": post-install,post-upgrade
    "helm.sh/hook-delete-policy": hook-succeeded
    "helm.sh/hook-weight": "5"
    {{- with .Values.initJob.annotations }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
spec:
  backoffLimit: {{ .Values.initJob.backoffLimit }}
  activeDeadlineSeconds: {{ .Values.initJob.activeDeadlineSeconds }}
  template:
    metadata:
      labels:
        {{- include "postgres.selectorLabels" . | nindent 8 }}
        {{- with .Values.initJob.labels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      restartPolicy: OnFailure
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      containers:
        - name: initdb
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          securityContext:
            {{- toYaml .Values.containerSecurityContext | nindent 12 }}
          env:
            - name: PGHOST
              value: {{ include "postgres.serviceHeadlessName" . }}
            - name: PGPORT
              value: "{{ .Values.service.port }}"
            - name: PGUSER
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: postgresUsername
            - name: PGPASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: postgresPassword
            - name: APP_DB
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: appDatabase
            - name: APP_USER
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: appUsername
            - name: APP_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres.secretName" . }}
                  key: appPassword
          command:
            - sh
            - -ceu
            - |
              echo "Waiting for PostgreSQL to be ready at ${PGHOST}:${PGPORT} ..."
              until pg_isready -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres; do
                sleep 2
              done
              echo "PostgreSQL is ready. Initializing application database and user..."

              # Create or update application role
              ROLE_EXISTS=$(psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres -Atqc "SELECT 1 FROM pg_roles WHERE rolname='${APP_USER}'" || true)
              if [ "${ROLE_EXISTS}" != "1" ]; then
                psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres -v ON_ERROR_STOP=1 -c "CREATE ROLE \"${APP_USER}\" LOGIN PASSWORD '${APP_PASSWORD}'"
                echo "Created role ${APP_USER}"
              else
                psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres -v ON_ERROR_STOP=1 -c "ALTER ROLE \"${APP_USER}\" LOGIN PASSWORD '${APP_PASSWORD}'"
                echo "Updated password for role ${APP_USER}"
              fi

              # Create database if it does not exist
              DB_EXISTS=$(psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres -Atqc "SELECT 1 FROM pg_database WHERE datname='${APP_DB}'" || true)
              if [ "${DB_EXISTS}" != "1" ]; then
                psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres -v ON_ERROR_STOP=1 -c "CREATE DATABASE \"${APP_DB}\" OWNER \"${APP_USER}\" ENCODING 'UTF8' TEMPLATE template0"
                echo "Created database ${APP_DB}"
              else
                echo "Database ${APP_DB} already exists"
              fi

              # Ensure ownership and privileges
              psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d postgres -v ON_ERROR_STOP=1 -c "ALTER DATABASE \"${APP_DB}\" OWNER TO \"${APP_USER}\""
              psql -h "${PGHOST}" -p "${PGPORT}" -U "${PGUSER}" -d "${APP_DB}" -v ON_ERROR_STOP=1 -c "GRANT ALL PRIVILEGES ON DATABASE \"${APP_DB}\" TO \"${APP_USER}\""
          resources:
            {{- toYaml .Values.resources | nindent 12 }}

