# FILE: Chart.yaml
apiVersion: v2
name: postgres
description: Helm chart to deploy a PostgreSQL database (non-production) with StatefulSet, headless Service, PVC, Secret for credentials, and an init Job to create the application database.
type: application
version: 0.1.0
appVersion: "16"
kubeVersion: ">=1.22.0-0"
home: https://www.postgresql.org/
keywords:
  - postgres
  - postgresql
  - database
maintainers:
  - name: DevOps Team
    email: devops@example.com
sources:
  - https://github.com/library/postgres
---
# FILE: values.yaml
nameOverride: ""
fullnameOverride: ""

image:
  repository: postgres
  tag: "16.4"
  pullPolicy: IfNotPresent

imagePullSecrets: []
# - name: myRegistryKeySecretName

replicaCount: 1

service:
  port: 5432
  annotations: {}
  labels: {}

persistence:
  enabled: true
  accessModes:
    - ReadWriteOnce
  size: 10Gi
  storageClass: ""

resources:
  limits:
    cpu: 500m
    memory: 512Mi
  requests:
    cpu: 100m
    memory: 256Mi

podAnnotations: {}
podLabels: {}

nodeSelector: {}
tolerations: []
affinity: {}

podSecurityContext:
  fsGroup: 999
  fsGroupChangePolicy: OnRootMismatch
  seccompProfile:
    type: RuntimeDefault

containerSecurityContext:
  runAsNonRoot: true
  runAsUser: 999
  runAsGroup: 999
  allowPrivilegeEscalation: false
  readOnlyRootFilesystem: false
  capabilities:
    drop:
      - ALL

probes:
  liveness:
    enabled: true
    initialDelaySeconds: 30
    periodSeconds: 10
    timeoutSeconds: 5
    failureThreshold: 6
  readiness:
    enabled: true
    initialDelaySeconds: 10
    periodSeconds: 10
    timeoutSeconds: 5
    failureThreshold: 6
  startup:
    enabled: true
    failureThreshold: 30
    periodSeconds: 10

terminationGracePeriodSeconds: 60

postgresql:
  username: postgres
  password: ""        # If empty, a password will be auto-generated and persisted in the Secret
  database: appdb
  appUser: appuser
  appPassword: ""     # If empty, a password will be auto-generated and persisted in the Secret

initJob:
  backoffLimit: 6
  activeDeadlineSeconds: 300
  annotations: {}
  labels: {}

priorityClassName: ""

---
# FILE: templates/_helpers.tpl
{{- define "postgres.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" -}}
{{- end -}}

{{- define "postgres.fullname" -}}
{{- if .Values.fullnameOverride -}}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- $name := include "postgres.name" . -}}
{{- if contains $name .Release.Name -}}
{{- .Release.Name | trunc 63 | trimSuffix "-" -}}
{{- else -}}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" -}}
{{- end -}}
{{- end -}}
{{- end -}}

{{- define "postgres.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" -}}
{{- end -}}

{{- define "postgres.labels" -}}
helm.sh/chart: {{ include "postgres.chart" . }}
app.kubernetes.io/name: {{ include "postgres.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- with .Values.podLabels }}
{{ toYaml . | indent 0 }}
{{- end }}
{{- end -}}

{{- define "postgres.selectorLabels" -}}
app.kubernetes.io/name: {{ include "postgres.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end -}}

{{- define "postgres.serviceHeadlessName" -}}
{{ include "postgres.fullname" . }}-headless
{{- end -}}

{{- define "postgres.secretName" -}}
{{ include "postgres.fullname" . }}-credentials
{{- end -}}
---
# FILE: templates/secret.yaml
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "postgres.secretName" . }}
  labels:
    {{- include "postgres.labels" . | nindent 4 }}
type: Opaque
data:
  {{- $existing := (lookup "v1" "Secret" .Release.Namespace (include "postgres.secretName" .)) }}
  {{- $creds := dict -}}
  {{- /* postgres username */ -}}
  {{- $_ := set $creds "pgUser" (.Values.postgresql.username | default "postgres") -}}
  {{- /* postgres password: prefer value, else existing secret, else generate */ -}}
  {{- if .Values.postgresql.password }}
    {{- $_ := set $creds "pgPass" .Values.postgresql.password -}}
  {{- else if $existing }}
    {{- $_ := set $creds "pgPass" (b64dec (index $existing.data "postgresPassword")) -}}
  {{- else }}
    {{- $_ := set $creds "pgPass" (randAlphaNum 24) -}}
  {{- end -}}
  {{- /* app database name */ -}}
  {{- $_ := set $creds "appDb" (.Values.postgresql.database | default "appdb") -}}
  {{- /* app username */ -}}
  {{- $_ := set $creds "appUser" (.Values.postgresql.appUser | default "appuser") -}}
  {{- /* app password: prefer value, else existing secret, else generate */ -}}
  {{- if .Values.postgresql.appPassword }}
    {{- $_ := set $creds "appPass" .Values.postgresql.appPassword -}}
  {{- else if $existing }}
    {{- $_ := set $creds "appPass" (b64dec (index $existing.data "appPassword")) -}}
  {{- else }}
    {{- $_ := set $creds "appPass" (randAlphaNum 24) -}}
  {{- end }}

  postgresUsername: {{ get $creds "pgUser" | b64enc | quote }}
  postgresPassword: {{ get $creds "pgPass" | b64enc | quote }}
  appDatabase: {{ get $creds "appDb" | b64enc | quote }}
  appUsername: {{ get $creds "appUser" | b64enc | quote }}
  appPassword: {{ get $creds "appPass" | b64enc | quote }}
